Tests for round 1 of the fishery simulation norm implementation.
"""

import json
import pytest
from pathlib import Path

def test_R1_object_calibrated_net_scale_exists():
    """
    Test that object type exists and configured.
    Agent knows their catch weight immediately after setting the net.
    """
    # Verify object type exists in institution.json
    institution = json.loads(Path("state/institution.json").read_text())
    assert "calibrated_net" in institution["object_types"]

    # Verify object is referenced in state objects
    objects = json.loads(Path("state/objects.json").read_text())
    # The objects file is a list of object instances
    calibrated_net_found = False
    for obj in objects:
        if obj.get("id") == "calibrated_net":
            calibrated_net_found = True
            break
    assert calibrated_net_found

def test_R2_action_return_excess_catch_enforcement():
    """
    Test that return excess catch rule enforces 0.75 unit threshold.
    Agent knows if their catch exceeds 0.75 units and must decide whether to return excess.
    """
    # Verify action exists in institution.json
    institution = json.loads(Path("state/institution.json").read_text())
    assert "return_excess_catch" in institution["actions"]

    # Verify action spec file exists and is properly configured
    action_file = Path("state/actions/return_excess_catch.json")
    assert action_file.exists()
    action_spec = json.loads(action_file.read_text())
    assert action_spec["name"] == "return_excess_catch"
    assert action_spec["roles"]["actor_role"] == "fisher"


def test_R3_role_designated_elder_exists():
    """
    Test that designated elder role exists.
    Agent knows their responsibility to collect and record surplus.
    """
    # Verify role exists in institution.json
    institution = json.loads(Path("state/institution.json").read_text())
    assert "elder" in institution["roles"]

    # Verify role is exclusive
    assert institution["roles"]["elder"]["exclusive"] is True

def test_R4_action_record_surplus_ledger_exists():
    """
    Test that record surplus in ledger action exists.
    Agent knows surplus collection and recording procedures.
    """
    # Verify action exists in institution.json
    institution = json.loads(Path("state/institution.json").read_text())
    assert "record_surplus" in institution["actions"]

    # Verify action spec file exists
    action_file = Path("state/actions/record_surplus.json")
    assert action_file.exists()
    action_spec = json.loads(action_file.read_text())
    assert action_spec["name"] == "record_surplus"
    assert action_spec["roles"]["actor_role"] == "elder"

def test_R5_role_scribe_exists():
    """
    Test that scribe maintaining communal ledger role exists.
    Agent knows their responsibility to maintain the ledger.
    """
    # Verify role exists in institution.json
    institution = json.loads(Path("state/institution.json").read_text())
    assert "scribe" in institution["roles"]

    # Verify role is exclusive
    assert institution["roles"]["scribe"]["exclusive"] is True

def test_R6_action_calculate_deficits_enforcement():
    """
    Test that calculate deficits action exists and is registered with proper rule.
    Agent knows how to calculate deficits and distribute surplus.
    """
    # Verify action exists in institution.json
    institution = json.loads(Path("state/institution.json").read_text())
    assert "calculate_deficits" in institution["actions"]

    # Verify action spec file exists and is properly configured
    action_file = Path("state/actions/calculate_deficits.json")
    assert action_file.exists()
    action_spec = json.loads(action_file.read_text())
    assert action_spec["name"] == "calculate_deficits"
    assert action_spec["roles"]["actor_role"] == "elder"

    # Verify rule has been activated (check config)
    config = json.loads(Path("state/config.json").read_text())
    assert "calculate_deficits" in config["rules"]
    assert len(config["rules"]["calculate_deficits"]) > 0
    assert config["rules"]["calculate_deficits"][0]["type"] == "surplus_calculation"

def test_R7_action_draw_from_reserve_enforcement():
    """
    Test that draw from reserve action exists and is registered with proper rule.
    Agent knows procedures for using the Reserve Balance.
    """
    # Verify action exists in institution.json
    institution = json.loads(Path("state/institution.json").read_text())
